fn handle_mcp_requests(&mut self) {
    while let Ok(request) = self.mcp_requests.try_recv() {
        let response = match self.authoring_windows.handle_mcp_tool_call(
            self.app.project_root(),
            self.app.asset_manifest(),
            request.name(),
            request.arguments().clone(),
        ) {
            Some(Ok(value)) => EditorMcpHostResult::Success(value),
            Some(Err(error)) => EditorMcpHostResult::ToolError {
                code: error.code().to_owned(),
                message: error.message().to_owned(),
            },
            None => match self
                .app
                .handle_mcp_tool_call(request.name(), request.arguments().clone())
            {
                Ok(value) => EditorMcpHostResult::Success(value),
                Err(error) => EditorMcpHostResult::ToolError {
                    code: error.code().to_owned(),
                    message: error.message().to_owned(),
                },
            },
        };
        request.respond(response);
    }
}
